describe('Password Strength Indicator', () => {
    beforeEach(() => {
        cy.visit('/signup'); // Adjust the URL to your signup page
    });

    it('should display the password strength indicator when a new password is entered', () => {
        cy.get('input[name="password"]').type('StrongPassword123!');
        cy.get('.password-strength-indicator').should('be.visible');
        cy.get('.password-strength-indicator').should('contain', 'Strong');
    });

    it('should indicate weak password strength for a short password', () => {
        cy.get('input[name="password"]').type('123');
        cy.get('.password-strength-indicator').should('be.visible');
        cy.get('.password-strength-indicator').should('contain', 'Weak');
    });
});
